import {cityGrowthGuide} from './city-growth-guide.js?v=medical-research-center-1';
import {utilityTrendSnapshot} from './utility-trends.js?v=medical-research-center-1';
const number=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1});
export function townGoals(city){const s=city.stats,u=utilityTrendSnapshot(city),types=['residential','commercial','industrial'],missing=types.filter(type=>!city.tiles.some(t=>t.type===type)),workers=s.commuters||0,employed=Math.max(0,workers-(s.unemployed||0)),last=city.history.at(-1),collected=last?['garbageRecycled','garbageIncinerated','garbageLandfilled','garbageExported'].reduce((sum,k)=>sum+(last[k]||0),0):0,cleanMonth=last?.month===city.month&&last.garbageGenerated>0&&collected>0&&last.garbageUncollected<1e-7&&s.uncollectedWaste<1e-7;
 return[
 {id:'roads',phase:'Foundations',title:'Build 10 road tiles',done:city.goals.roads>=10,detail:`${Math.min(10,city.goals.roads)} / 10 new road tiles. Connect homes and workplaces to the same network.`,action:'road',button:'Choose roads'},
 {id:'zones',phase:'Foundations',title:'Zone homes and workplaces',done:city.goals.zones>=10&&!missing.length,detail:`${Math.min(10,city.goals.zones)} / 10 new zone tiles. ${missing.length?'Still needed: '+missing.join(', ')+'.':'All three zone types are present.'}`,action:missing[0]||'residential',button:'Choose the next zone'},
 {id:'power',phase:'Foundations',title:'Connect electricity',done:u.powerDemand>0&&u.powerUnserved<1e-7,detail:`${number(s.powerServed)} / ${number(u.powerDemand)} power demand served. Local plants or connected imports can supply the town.`,action:u.powerAvailable>0?'utilities':'coal',button:u.powerAvailable>0?'Inspect utility networks':'Choose a coal plant'},
 {id:'residents',phase:'Foundations',title:'Welcome new residents',done:city.goals.grown&&s.population>=80,detail:`${number(s.population)} / 80 residents. Run the simulation after connecting roads, zones and electricity.`,action:'play',button:'Run the city'},
 {id:'water',phase:'A functioning town',title:'Supply the town with water',done:u.waterDemand>0&&u.waterUnserved<1e-7,detail:`${number(s.waterUsed)} / ${number(u.waterDemand)} water demand served. Connect powered sources to pipes; spare capacity cannot cross a broken network.`,action:'utilities',button:'Plan water service'},
 {id:'jobs',phase:'A functioning town',title:'Connect residents to jobs',done:workers>0&&employed/workers>=.9,detail:`${number(employed)} / ${number(workers)} workers reach jobs. Aim for at least 90% in this introductory exercise; connect workplaces and check transport condition.`,action:'transport',button:'Inspect commuting'},
 {id:'waste',phase:'A functioning town',title:'Complete a clean collection month',done:s.population>0&&!!cleanMonth,detail:cleanMonth?'The latest simulated month generated and collected waste with no backlog remaining.':'Run a month with working disposal and no uncollected garbage. Road-connected landfill is an early option; recycling, incineration and exports also count.',action:'utilities',button:'Plan waste collection'},
 {id:'budget',phase:'A functioning town',title:'Run three surplus months',done:s.population>=80&&city.funds>=0&&city.finance.monthsInSurplus>=3,detail:`${Math.min(3,city.finance.monthsInSurplus)} / 3 consecutive surplus months · treasury §${number(city.funds)}. Keep at least 80 residents and a nonnegative treasury.`,action:'budget',button:'Review the budget'}
 ];
}
export function showTownGuide(ui){const city=ui.city(),goals=townGoals(city);ui.dialog('Build your first town',`<p>${city.starter?'You are expanding a starter town. Use the city menu to start on empty land instead.':'You are starting on empty land. Begin with two crossing roads.'} The simulation is paused so you can plan.</p><p>These checks describe your town now. Service and budget checks can become incomplete again if conditions deteriorate.</p>${['Foundations','A functioning town'].map(phase=>`<h3>${phase}</h3><ol>${goals.filter(g=>g.phase===phase).map(g=>`<li><strong class="${g.done?'check':''}">${g.done?'✓ ':''}${g.title}</strong><p>${g.detail}</p><button data-town-action="${g.action}">${g.button}</button></li>`).join('')}</ol>`).join('')}<p>Light zones can grow before water arrives. Reliable water supports further development. A three-month surplus and 90% job access are introductory targets, not recovered original-game victory rules.</p>${cityGrowthGuide(city)}<div class="actions"><button id="returnPlay" class="primary">Back to my city</button><button id="reviewFromGuide">Milestone feedback</button></div>`);
 document.querySelectorAll('[data-town-action]').forEach(button=>button.onclick=()=>{const action=button.getAttribute('data-town-action');if(['utilities','transport','budget','play'].includes(action))ui[action]();else if(['road','residential','commercial','industrial','coal','park'].includes(action)){ui.close();ui.tool(action);}});document.getElementById('returnPlay').onclick=ui.close;document.getElementById('reviewFromGuide').onclick=ui.review;
}
